pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 msgValue) public {
        vm.assume(msgValue < address(this).balance - 1 ether);
        vm.deal(address(this), msgValue);

        bool reverted;
        try c.go{value: msgValue}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assertTrue((reverted && address(c).balance == msgValue) || (!reverted && address(c).balance == 0));
    }
}

