pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= address(c).balance);
        // Fund the contract so it can send ETH
        vm.deal(address(c), amount);
        // Record balance before go()
        uint256 balanceBefore = address(c).balance;
        // Call go() - it will try to send ETH to target and then transfer all balance to owner
        (bool success, ) = address(c).call{value: 0}("");
        if (!success) {
            // If call reverts, test is invalid, skip
            return;
        }
        // After go(), contract balance should be zero because all funds are transferred
        assertTrue(address(c).balance == 0, "Contract balance after go() must be zero");
    }
}

