        vm.assume(amount <= address(this).balance);

        uint256 balanceBefore = owner.balance;

        // Drive the contract through go() with the fuzz amount
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("go()"));

        // The call must succeed
        assertTrue(success);

        // General rule: owner's balance increases by exactly the amount sent
        assertTrue(owner.balance == balanceBefore + amount);
    }
}

