pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 msgValue) public {
        msgValue = bound(msgValue, 0, 100 ether);
        address target = 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C;
        uint256 targetBefore = target.balance;
        uint256 contractBefore = address(c).balance;
        vm.deal(address(c), contractBefore + msgValue);
        (bool success, ) = address(c).call{value: msgValue}(abi.encodeWithSignature("go()"));
        assertTrue(success);
        uint256 contractAfter = address(c).balance;
        uint256 targetAfter = target.balance;
        assertTrue(contractBefore + msgValue + targetBefore == contractAfter + targetAfter);
    }
